// Entrada: debes conectar Google Sheets56 en input[0] y Google Sheets57 en input[1]

const historial = $items("Google Sheets1").map(item => item.json)
const vendedores = $items("Google Sheets").map(item => item.json);

// 1. Si historial está vacío, devolvemos el primer vendedor (Orden más bajo)
if (historial.length === 0) {
  const primero = vendedores.reduce((min, v) => v.Orden < min.Orden ? v : min, vendedores[0]);
  return [{ json: primero }];
}

// 2. Tomar el último registro de historial (mayor row_number)
const ultimoHistorial = historial.reduce((max, item) => 
  item.row_number > max.row_number ? item : max, historial[0]);

const vendedorActual = ultimoHistorial.Orden;

// 3. Calcular el siguiente vendedor
const maxOrden = Math.max(...vendedores.map(v => v.Orden));
let siguiente = vendedorActual + 1;

// Si supera el máximo, reinicia a 0
if (siguiente > maxOrden) siguiente = 0;

// 4. Buscar el vendedor en base al Orden
const vendedorAsignado = vendedores.find(v => v.Orden === siguiente);

// 5. Si solo hay un vendedor, devolver ese
let salida;
if (maxOrden === 0) {
  salida = vendedores[0];
} else {
  salida = vendedorAsignado || vendedores[0]; // fallback por seguridad
}

// Retornar
return [{json: salida}];

